PARTIAL_CHUNK = 65_536  # 64 KB

def compute_partial_hash(filepath):
    try:
        size = os.path.getsize(filepath)
        h = xxhash.xxh64()
        with open(filepath, "rb") as f:
            h.update(f.read(PARTIAL_CHUNK))
            if size > PARTIAL_CHUNK * 2:
                f.seek(-PARTIAL_CHUNK, 2)
                h.update(f.read(PARTIAL_CHUNK))
        return h.hexdigest(), None
    except FileNotFoundError:
        return None, "missing"
    except (PermissionError, OSError):
        return None, "inaccessible"

def get_category(extension, categories):
    ext_lower = (extension or "").lower()
    for category, extensions in categories.items():
        if ext_lower in extensions:
            return category
    return "Other"

def get_archive_era(modified_date, forward_year=FORWARD_YEAR):
    try:
        dt = datetime.fromisoformat(modified_date)
        year = dt.year
        if year >= forward_year:
            return "FORWARD", year
        return "BACKWARD", year
    except (ValueError, TypeError, AttributeError):
        return "FORWARD", datetime.now().year

